#!/usr/bin/env bash
# End-to-end suite (Playwright): a mock upstream instead of the network, the production build on :3000, and every
# test file starting from the same baseline DB (no order dependency).
#   bash e2e/runall.sh                 # baseline generated by make-fixture.sh
#   bash e2e/runall.sh base.db t3 t12  # given baseline, some tests
# Needs `npm run build` first. Exit code 1 when any check fails.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"; cd "$ROOT"
TMP="$(mktemp -d)"; MOCK_PORT="${MOCK_PORT:-4010}"
export UPSTREAM_MOCK="http://127.0.0.1:$MOCK_PORT" MOCK_PORT FX_TRIES=2 FX_TIMEOUT_MS=3000 NOTIFY_BATCH_MS=1500 NOTIFY_MIN_GAP_MS=0
export E2E_LOG="${E2E_LOG:-$TMP/server.log}"
pkill -f "node e2e/mock-upstream.mjs" 2>/dev/null; sleep 0.3
node e2e/mock-upstream.mjs > "$TMP/mock.log" 2>&1 & MOCK_PID=$!
cleanup() { kill "$MOCK_PID" 2>/dev/null; for p in $(pgrep -f next-server || true); do kill "$p" 2>/dev/null; done; }
trap cleanup EXIT
for i in $(seq 40); do curl -sf "$UPSTREAM_MOCK/__ctl?state=1" -o /dev/null && break; sleep 0.25; done
BASE="${1:-}"; shift || true
if [ -z "$BASE" ]; then BASE="$TMP/baseline.db"; bash e2e/make-fixture.sh "$BASE" || { echo "fixture failed"; exit 1; }; fi
TESTS="${*:-t1 t2 t3 t4 t5 t6 t7 t8 t9 t10 t11 t12 t13 t14 t15 t16}"
pass=0; failn=0; failed=""
for t in $TESTS; do
  for p in $(pgrep -f next-server || true); do kill -9 "$p" 2>/dev/null; done; sleep 0.5
  rm -f data/news.db-wal data/news.db-shm data/secrets.json; cp "$BASE" data/news.db
  curl -sf "$UPSTREAM_MOCK/__ctl?reset=1" -o /dev/null
  bash e2e/restart.sh >/dev/null
  bash e2e/fixtures.sh
  echo "== $t"
  out="$(cd e2e && node "$t.mjs" 2>&1)"; rc=$?
  echo "$out"
  p=$(grep -c '^PASS' <<<"$out"); f=$(grep -c '^FAIL' <<<"$out"); pass=$((pass + p)); failn=$((failn + f))
  if [ "$rc" -ne 0 ] || [ "$f" -gt 0 ]; then failed="$failed $t"; [ "$rc" -ne 0 ] && echo "CRASH $t (exit $rc)"; fi
done
echo "== summary: $pass passed, $failn failed${failed:+ (in:$failed)}"
[ -z "$failed" ]
